const {chromium}=require('playwright'),fs=require('fs'),os=require('os'),path=require('path'),http=require('http'),assert=require('assert/strict'),{execFileSync}=require('child_process');const repo=path.resolve(__dirname,'../..'),dir=fs.mkdtempSync(path.join(os.tmpdir(),'sambaadm-helper-install-'));execFileSync('go',['test','./internal/web','-run','^TestWorkspaceBrowserFixtures$','-count=1'],{cwd:repo,env:{...process.env,SAMBAADM_WEB_FIXTURE_DIR:dir}});const server=http.createServer((req,res)=>{const p=new URL(req.url,'http://localhost').pathname,file=p.startsWith('/static/')?path.join(repo,'internal/web',p):path.join(dir,'admin-settings_helpers.html');if(!fs.existsSync(file)){res.writeHead(404).end();return;}res.setHeader('Content-Type',file.endsWith('.js')?'application/javascript':file.endsWith('.css')?'text/css':'text/html');res.end(fs.readFileSync(file));});
(async()=>{await new Promise(r=>server.listen(0,'127.0.0.1',r));const browser=await chromium.launch({headless:true});try{const page=await browser.newPage({viewport:{width:1440,height:1000}}),errors=[],writes=[];let job;page.on('pageerror',e=>errors.push(e.message));await page.route('**/api/v1/**',async route=>{const req=route.request(),p=new URL(req.url()).pathname;let result={jobs:job?[job]:[],packages:{x86_64:true,aarch64:false},version:'0.45.20'};if(p.endsWith('/sites/controllers'))result=[{dns:'dc1.example.com',site:'Головной офис',rodc:false},{dns:'rodc.example.com',site:'Филиал',rodc:true}];if(req.method()==='POST'){const b=req.postDataJSON();assert(req.headers()['x-csrf-token']);writes.push(b);if(b.action==='probe'){assert.deepEqual(b.nodes,['dc1.example.com']);job={id:'plan',created:new Date().toISOString(),status:'ready',nodes:[{node:'dc1.example.com',fingerprint:'SHA256:verified-key',phase:'ready',logs:['Ключ SSH получен']} ]};}else{assert.equal(b.password,'ssh-secret');assert.equal(b.rootPassword,'root-secret');assert.equal(b.confirm,true);job={...job,status:'complete',nodes:[{...job.nodes[0],phase:'complete',logs:['Копирование RPM','Установка пакета','Привязка и подписанный запрос HTTPS проверены']}]};}result=job;}if(req.method()==='GET'&&job?.status==='ready')await new Promise(r=>setTimeout(r,300));await route.fulfill({json:result});});await page.goto('http://127.0.0.1:'+server.address().port+'/settings/helpers?node=dc1.example.com');const root=page.locator('[data-helper-install]');await root.getByText('dc1.example.com',{exact:true}).waitFor();assert.equal(await root.locator('[data-install-credentials]').isVisible(),false);await root.getByRole('button',{name:'Проверить SSH',exact:true}).click();await root.getByText('SHA256:verified-key',{exact:true}).waitFor();const credentials=root.locator('[data-install-credentials]');await credentials.getByLabel('Логин SSH',{exact:true}).fill('tester');await credentials.getByLabel('Пароль SSH',{exact:true}).fill('ssh-secret');await credentials.getByLabel('Пароль для su -',{exact:true}).fill('root-secret');assert.equal(await credentials.getAttribute('method'),'post');await credentials.getByRole('checkbox').first().check();await credentials.getByRole('button',{name:'Установить и привязать',exact:true}).click();await root.locator('.helper-install-job > summary').filter({hasText:'Готово'}).waitFor();if(!await root.locator('.helper-install-job').evaluate(e=>e.open))await root.locator('.helper-install-job > summary').click();await root.getByText('dc1.example.com · Готово',{exact:true}).waitFor();assert.equal(await credentials.isVisible(),false);assert.equal(await credentials.locator('[name=password]').inputValue(),'');assert.equal(await credentials.locator('[name=rootPassword]').inputValue(),'');assert(!await page.content().then(s=>s.includes('ssh-secret')||s.includes('root-secret')));await page.screenshot({path:path.join(dir,'helper-install-desktop.png'),fullPage:true});await page.reload();await root.locator('.helper-install-job > summary').filter({hasText:'Готово'}).waitFor();if(!await root.locator('.helper-install-job').evaluate(e=>e.open))await root.locator('.helper-install-job > summary').click();await root.getByText('dc1.example.com · Готово',{exact:true}).waitFor();assert.equal(writes.filter(b=>b.action==='start').length,1,'reload must not repeat installation');await page.setViewportSize({width:390,height:844});assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false);await page.screenshot({path:path.join(dir,'helper-install-mobile.png'),fullPage:true});assert.deepEqual(errors,[]);console.log('PASS helper controller selection, key confirmation, credentials/CSRF POST, password clearing, persistent logs, no repeat on reload and mobile. Screenshots:',dir);}finally{await browser.close();server.close();}})().catch(e=>{console.error(e);server.close();process.exitCode=1;});
